/**
 * Reproduces partial authoritative LMDB commits when a post-commit derived-state callback fails.
 */
class LmdbCommitAtomicityTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String LONG_SUFFIX = "x".repeat(256);
	private static final String GROWTH_SUFFIX = "g".repeat(64);
	private static final int GROWTH_ROWS = 32_768;
	private static final IRI SEED_SUBJECT = VF.createIRI("urn:lmdb-atomicity:seed:subject:" + LONG_SUFFIX);
	private static final IRI SEED_PREDICATE = VF.createIRI("urn:lmdb-atomicity:seed:predicate:" + LONG_SUFFIX);
	private static final Value SEED_OBJECT = VF.createLiteral("seed-object-" + LONG_SUFFIX);
	private static final Statement SEED = VF.createStatement(SEED_SUBJECT, SEED_PREDICATE, SEED_OBJECT);

	@TempDir
	Path dataDir;

	@Test
	@Timeout(60)
	void postCommitDerivedPublicationFailurePreservesTheCommittedModelSynchronously() throws Exception {
		exercisePostCommitPublicationFailure(false);
	}

	@Test
	@Timeout(60)
	void postCommitDerivedPublicationFailurePreservesTheCommittedModelAsynchronously() throws Exception {
		exercisePostCommitPublicationFailure(true);
	}

	@Test
	@Timeout(60)
	void autogrowCommitFailurePreservesTheCommittedModel() throws Exception {
		LmdbStoreConfig config = autogrowConfig();
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		store.init();
		Statement recovery = statement("recovery", 0);
		List<Statement> attempted = new ArrayList<>();
		for (int i = 0; i < GROWTH_ROWS; i++) {
			attempted.add(statement("growth", i));
		}
		Throwable commitFailure;
		int physicalCommitCalls;
		try {
			LmdbSailStore backing = store.getBackingStore();
			write(backing, SEED);
			AtomicInteger physicalCommitCount = new AtomicInteger();
			TripleStore tripleStore = backing.getTripleStore();
			tripleStore.beforePhysicalCommitForTest = () -> {
				if (physicalCommitCount.incrementAndGet() == 2) {
					throw new IllegalStateException("injected autogrow commit failure");
				}
			};

			commitFailure = capture(() -> write(backing, attempted));
			tripleStore.beforePhysicalCommitForTest = null;
			physicalCommitCalls = physicalCommitCount.get();
		} finally {
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			store.shutDown();
		}
		Set<Statement> expectedAfterFailure = commitFailure == null ? withSeed(attempted) : Set.of(SEED);
		Throwable stateFailure = capture(() -> assertModelAndDictionaryResolve(dataDir.toFile(), config,
				expectedAfterFailure));
		Throwable recoveryFailure = capture(() -> {
			LmdbStore recovered = new LmdbStore(dataDir.toFile(), config);
			recovered.init();
			try {
				write(recovered.getBackingStore(), recovery);
			} finally {
				recovered.shutDown();
			}
			Set<Statement> expectedAfterRecovery = new LinkedHashSet<>(expectedAfterFailure);
			expectedAfterRecovery.add(recovery);
			assertModelAndDictionaryResolve(dataDir.toFile(), config, expectedAfterRecovery);
		});
		assertAll(
				() -> assertThat(commitFailure == null || physicalCommitCalls >= 2
						&& commitFailure.getMessage() != null
						&& commitFailure.getMessage().contains("injected autogrow commit failure"))
								.as("the injected second physical commit must either fail there or be eliminated")
								.isTrue(),
				() -> assertThat(physicalCommitCalls).isGreaterThanOrEqualTo(1),
				() -> assertThat(stateFailure).as("reopened state must be complete and resolvable").isNull(),
				() -> assertThat(recoveryFailure).as("a new write must work after the failed commit").isNull());
	}

	@Test
	@Timeout(60)
	void autogrowCommitWithCacheReplayCompletesInOnePhysicalCommit() throws Exception {
		LmdbStoreConfig config = autogrowConfig();
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		store.init();
		List<Statement> attempted = new ArrayList<>();
		for (int i = 0; i < GROWTH_ROWS; i++) {
			attempted.add(statement("success", i));
		}
		AtomicInteger physicalCommitCount = new AtomicInteger();
		try {
			LmdbSailStore backing = store.getBackingStore();
			write(backing, SEED);
			backing.getTripleStore().beforePhysicalCommitForTest = physicalCommitCount::incrementAndGet;
			write(backing, attempted);
		} finally {
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			store.shutDown();
		}

		assertThat(physicalCommitCount.get())
				.as("a growing commit must publish one authoritative physical commit")
				.isEqualTo(1);
		assertModelAndDictionaryResolve(dataDir.toFile(), config, withSeed(attempted));
	}

	@Test
	@Timeout(60)
	void autogrowCommitFailureBeforeTheFirstPhysicalCommitLeavesThePreexistingModel() throws Exception {
		LmdbStoreConfig config = autogrowConfig();
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		store.init();
		AtomicInteger physicalCommitCount = new AtomicInteger();
		Throwable commitFailure;
		try {
			LmdbSailStore backing = store.getBackingStore();
			write(backing, SEED);
			backing.getTripleStore().beforePhysicalCommitForTest = () -> {
				physicalCommitCount.incrementAndGet();
				throw new IllegalStateException("injected first physical commit failure");
			};
			commitFailure = capture(() -> write(backing, statement("first-failure", 0)));
		} finally {
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			store.shutDown();
		}

		assertAll(
				() -> assertThat(commitFailure).hasMessageContaining("injected first physical commit failure"),
				() -> assertThat(physicalCommitCount.get()).isEqualTo(1),
				() -> assertModelAndDictionaryResolve(dataDir.toFile(), config, Set.of(SEED)));
	}

	private void exercisePostCommitPublicationFailure(boolean enableMultiThreading) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setBulkOperationSize(0)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyBuildOnStart(false);
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		store.init();
		Statement attempted = VF.createStatement(
				VF.createIRI("urn:lmdb-atomicity:attempted:subject:" + LONG_SUFFIX),
				VF.createIRI("urn:lmdb-atomicity:attempted:predicate:" + LONG_SUFFIX),
				VF.createLiteral("attempted-object-" + LONG_SUFFIX),
				VF.createIRI("urn:lmdb-atomicity:attempted:context:" + LONG_SUFFIX));
		Statement recovery = VF.createStatement(
				VF.createIRI("urn:lmdb-atomicity:recovery:subject:" + LONG_SUFFIX),
				VF.createIRI("urn:lmdb-atomicity:recovery:predicate:" + LONG_SUFFIX),
				VF.createLiteral("recovery-object-" + LONG_SUFFIX),
				VF.createIRI("urn:lmdb-atomicity:recovery:context:" + LONG_SUFFIX));
		AtomicBoolean failOnce = new AtomicBoolean();
		Throwable commitFailure;

		try {
			LmdbSailStore backing = store.getBackingStore();
			backing.enableMultiThreading = enableMultiThreading;
			write(backing, SEED);

			LmdbDirectAdjacencyStore adjacency = backing.directAdjacencyStore();
			assertThat(adjacency).as("the reproducer requires the direct-adjacency commit callback").isNotNull();
			TripleStore tripleStore = backing.getTripleStore();
			TripleStore.DirectAdjacencyCommitListener delegate = adjacency.commitListener();
			tripleStore.setDirectAdjacencyCommitHooks((delta, nextRevision) -> {
				delegate.beforeRevisionBump(delta, nextRevision);
				if (failOnce.compareAndSet(false, true)) {
					throw new IllegalStateException("injected derived publication failure");
				}
			}, adjacency.newCommitDelta());

			commitFailure = capture(() -> write(backing, attempted));
			tripleStore.setDirectAdjacencyCommitHooks(delegate, adjacency.newCommitDelta());
		} finally {
			store.shutDown();
		}

		Throwable stateFailure = capture(() -> assertModelAndDictionaryResolve(dataDir.toFile(), config,
				Set.of(SEED, attempted)));
		Throwable recoveryFailure = capture(() -> {
			LmdbStore recovered = new LmdbStore(dataDir.toFile(), config);
			recovered.init();
			try {
				write(recovered.getBackingStore(), recovery);
			} finally {
				recovered.shutDown();
			}
			Set<Statement> expectedAfterRecovery = new LinkedHashSet<>(Set.of(SEED, attempted));
			expectedAfterRecovery.add(recovery);
			assertModelAndDictionaryResolve(dataDir.toFile(), config, expectedAfterRecovery);
		});
		assertAll(
				() -> assertThat(failOnce.get()).isTrue(),
				() -> assertThat(commitFailure)
						.as("derived publication failure must not abort the authoritative commit")
						.isNull(),
				() -> assertThat(stateFailure).as("reopened state must be complete and resolvable").isNull(),
				() -> assertThat(recoveryFailure).as("a new write must work after the failed commit").isNull());
	}

	private static void write(LmdbSailStore backing, Statement statement) {
		write(backing, List.of(statement));
	}

	private static void write(LmdbSailStore backing, Iterable<? extends Statement> statements) {
		try (SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			for (Statement statement : statements) {
				sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
						statement.getContext());
			}
			sink.flush();
		}
	}

	private static void assertModelAndDictionaryResolve(File dataDir, LmdbStoreConfig config,
			Set<Statement> expected) throws Exception {
		LmdbStore recovered = new LmdbStore(dataDir, config);
		recovered.init();
		try {
			LmdbSailStore backing = recovered.getBackingStore();
			ValueStore valueStore = (ValueStore) backing.getValueFactory();
			List<Statement> actual = new ArrayList<>();
			try (SailDataset dataset = backing.getExplicitSailSource().dataset(IsolationLevels.READ_COMMITTED);
					CloseableIteration<? extends Statement> statements = dataset.getStatements(null, null, null)) {
				while (statements.hasNext()) {
					Statement statement = statements.next();
					assertStatementDictionaryIds(valueStore, statement);
					actual.add(statement);
				}
			}
			assertThat(actual).as("the durable statement count must match the committed model")
					.hasSize(expected.size());
			try (SailDataset dataset = backing.getExplicitSailSource().dataset(IsolationLevels.READ_COMMITTED)) {
				for (Statement statement : expected) {
					assertThat(dataset.hasStatements(statement.getSubject(), statement.getPredicate(),
							statement.getObject(),
							statement.getContext()))
									.as("expected statement must remain durable")
									.isTrue();
				}
			}

		} finally {
			recovered.shutDown();
		}
	}

	private static void assertStatementDictionaryIds(ValueStore valueStore, Statement statement) throws Exception {
		assertResolves(valueStore, statement.getSubject());
		assertResolves(valueStore, statement.getPredicate());
		assertResolves(valueStore, statement.getObject());
		if (statement.getContext() != null) {
			assertResolves(valueStore, statement.getContext());
		}
	}

	private static void assertResolves(ValueStore valueStore, Value value) throws Exception {
		long id = value instanceof LmdbValue lmdbValue ? lmdbValue.getInternalID() : LmdbValue.UNKNOWN_ID;
		if (id == LmdbValue.UNKNOWN_ID) {
			id = valueStore.getId(value);
		}
		assertThat(id).as("dictionary id must exist for value class %s", value.getClass().getName())
				.isNotEqualTo(LmdbValue.UNKNOWN_ID);
		LmdbValue resolved = valueStore.getValue(id);
		assertThat(resolved).as("dictionary value for internal id %s", id).isNotNull();
		assertThat(resolved.equals(value)).as("dictionary value must match id %s", id).isTrue();
	}

	private static Throwable capture(ThrowingRunnable action) {
		try {
			action.run();
			return null;
		} catch (Throwable failure) {
			return failure;
		}
	}

	@FunctionalInterface
	private interface ThrowingRunnable {
		void run() throws Throwable;
	}

	private static Statement statement(String kind, int index) {
		return VF.createStatement(
				VF.createIRI("urn:lmdb-atomicity:" + kind + ":subject:" + index + ":" + GROWTH_SUFFIX),
				VF.createIRI("urn:lmdb-atomicity:" + kind + ":predicate:" + GROWTH_SUFFIX),
				VF.createLiteral(kind + "-object-" + index + "-" + GROWTH_SUFFIX));
	}

	private static LmdbStoreConfig autogrowConfig() {
		return new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setBulkOperationSize(0)
				.setTripleDBSize(256L * 1024)
				.setValueDBSize(16L * 1024 * 1024)
				.setAutoGrow(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
	}

	private static Set<Statement> withSeed(Iterable<? extends Statement> statements) {
		Set<Statement> result = new LinkedHashSet<>();
		result.add(SEED);
		statements.forEach(result::add);
		return result;
	}
}
